---@type IDataInfo
local IDataInfo = Plugins.Require("data_info", isClient and "client.info.CDataInfo" or "server.info.SDataInfo")
---@class BulletinInfo : IDataInfo
local BulletinInfo = class("BulletinInfo", IDataInfo)
---@type BulletinConfig
local BulletinConfig = T(Global, "BulletinConfig")

function BulletinInfo:onCreate()
    ---key, defValue, toSelf, toOther, saveDB
    self:initKey(Define.BulletinInfoKey.IsOpenUI, false, true, false, false)
    local cfgs = BulletinConfig:getAllCfgs()
    for _, cfg in pairs(cfgs) do
        self:initKey(Define.BulletinInfoKey.Version .. cfg.id, 0, false, false, true)
    end
    self:initListener()
end

function BulletinInfo:initListener()
    if isServer then
        return
    end
    self:addKeyObserver(Define.BulletinInfoKey.IsOpenUI, function(_, _, value)
        if value then
            UIHelper.showGameGUILayout("GUIBulletin")
        end
    end)
end

function BulletinInfo:onPlayerReady()
    local cfgs = BulletinConfig:getAllCfgs()
    for _, cfg in pairs(cfgs) do
        local version = self:getValue(Define.BulletinInfoKey.Version .. cfg.id)
        if version < cfg.version then
            self:setValue(Define.BulletinInfoKey.Version .. cfg.id, cfg.version)
            self:setValue(Define.BulletinInfoKey.IsOpenUI, true)
        end
    end
end

return BulletinInfo